def creditar_sessoes_ja_concluidas(apps, schema_editor):
    """Quem já focava começa com o ATP das sessões que já concluiu: 1 por minuto,
    a mesma conta de `atp_da_sessao` (cada neurônio vivo é uma sessão concluída)."""
    NeuronioModel = apps.get_model("app", "NeuronioModel")
    CarteiraModel = apps.get_model("app", "CarteiraModel")
    minutos_por_usuario = (
        NeuronioModel.objects.filter(vivo=True)
        .order_by()
        .values("usuario_id")
        .annotate(minutos=Sum("duracao_minutos"))
    )
    CarteiraModel.objects.bulk_create(
        CarteiraModel(usuario_id=linha["usuario_id"], saldo=linha["minutos"])
        for linha in minutos_por_usuario
    )


